{
  "env": {
    "CLAUDE_CODE_EXPERIMENTAL_AGENT_TEAMS": "1"
  },
  "hooks": {
    "PreToolUse": [
      {
        "matcher": "mcp__.*__(GetTableContents|GetSqlQuery)",
        "hooks": [
          {
            "type": "command",
            "command": "node \"C:/Users/user/.claude/plugins/marketplaces/sc4sap/scripts/hooks/block-forbidden-tables.mjs\""
          }
        ]
      }
    ]
  },
  "statusLine": {
    "type": "command",
    "command": "node \"C:/Users/user/.claude/plugins/cache/sc4sap/sc4sap/0.3.5/scripts/hud/statusline.mjs\"",
    "padding": 0
  },
  "enabledPlugins": {
    "oh-my-claudecode@omc": false,
    "sc4sap@sc4sap": true,
    "notion@claude-plugins-official": true
  },
  "extraKnownMarketplaces": {
    "omc": {
      "source": {
        "source": "git",
        "url": "https://github.com/Yeachan-Heo/oh-my-claudecode.git"
      }
    },
    "sc4sap": {
      "source": {
        "source": "git",
        "url": "https://github.com/babamba2/superclaude-for-sap.git"
      }
    }
  },
  "theme": "dark-ansi"
}

