#!/usr/bin/env node
// SessionStart hook: attach Entire CLI to the current Claude Code session.
// Reads JSON {session_id} from stdin, runs `entire attach <session_id>`.
// Silent on success; surfaces errors to stderr; never blocks startup.

import { execFile } from 'node:child_process';

let raw = '';
process.stdin.setEncoding('utf8');
process.stdin.on('data', (chunk) => { raw += chunk; });
process.stdin.on('end', () => {
  let sid = '';
  try { sid = (JSON.parse(raw).session_id || '').trim(); } catch { /* ignore */ }
  if (!/^[0-9a-fA-F-]{8,}$/.test(sid)) { process.exit(0); }

  execFile('entire', ['attach', sid], { shell: true, windowsHide: true }, (err, stdout, stderr) => {
    if (err) {
      const msg = (stderr || stdout || err.message || '').toString().trim();
      // Distinguish missing CLI vs real failure — don't spam if entire isn't installed.
      if (/not recognized|command not found|ENOENT/i.test(msg)) { process.exit(0); }
      process.stderr.write(`entire attach failed: ${msg}\n`);
    }
    process.exit(0);
  });
});

