import fs from 'node:fs';

const root = process.argv[2];
const xml = fs.readFileSync(`${root}/xl/styles.xml`, 'utf8');

function parseList(tag) {
  const re = new RegExp(`<${tag}[^>]*>([\\s\\S]*?)<\\/${tag}>`);
  const m = re.exec(xml);
  if (!m) return [];
  return m[1];
}

function pickAll(text, tag) {
  const out = [];
  const re = new RegExp(`<${tag}(?:\\s[^>]*)?(?:/>|>([\\s\\S]*?)<\\/${tag}>)`, 'g');
  let m;
  while ((m = re.exec(text))) out.push({ outer: m[0], inner: m[1] || '' });
  return out;
}

// Fonts
const fontsBlock = parseList('fonts');
const fonts = pickAll(fontsBlock, 'font').map((f, i) => {
  const sz = /<sz val="([^"]+)"/.exec(f.inner)?.[1];
  const name = /<name val="([^"]+)"/.exec(f.inner)?.[1];
  const color = /<color rgb="([^"]+)"/.exec(f.inner)?.[1];
  const bold = /<b\s*\/?>/.test(f.inner) ? 'B' : '';
  const italic = /<i\s*\/?>/.test(f.inner) ? 'I' : '';
  return { i, sz, name, color, attr: bold + italic };
});

// Fills
const fillsBlock = parseList('fills');
const fills = pickAll(fillsBlock, 'fill').map((f, i) => {
  const pf = /<patternFill[^>]*patternType="([^"]+)"/.exec(f.inner)?.[1] || 'none';
  const fg = /<fgColor rgb="([^"]+)"/.exec(f.inner)?.[1] || '';
  const bg = /<bgColor rgb="([^"]+)"/.exec(f.inner)?.[1] || '';
  return { i, pf, fg, bg };
});

// Borders
const bordersBlock = parseList('borders');
const borders = pickAll(bordersBlock, 'border').map((f, i) => {
  function side(name) {
    const m = new RegExp(`<${name}([^/>]*)(?:/>|>)`).exec(f.inner);
    if (!m) return '-';
    const style = /style="([^"]+)"/.exec(m[1])?.[1] || '?';
    return style === 'thin' ? 'T' : style[0]?.toUpperCase() || '?';
  }
  return { i, l: side('left'), r: side('right'), t: side('top'), b: side('bottom') };
});

// CellXfs
const xfsBlock = parseList('cellXfs');
const xfs = pickAll(xfsBlock, 'xf').map((f, i) => {
  const inner = f.outer;
  const fontId = /fontId="(\d+)"/.exec(inner)?.[1] ?? '?';
  const fillId = /fillId="(\d+)"/.exec(inner)?.[1] ?? '?';
  const borderId = /borderId="(\d+)"/.exec(inner)?.[1] ?? '?';
  const numFmtId = /numFmtId="(\d+)"/.exec(inner)?.[1] ?? '?';
  const align = /<alignment([^/>]*)/.exec(f.inner || inner)?.[1] || '';
  const h = /horizontal="([^"]+)"/.exec(align)?.[1] || '';
  const v = /vertical="([^"]+)"/.exec(align)?.[1] || '';
  const wrap = /wrapText="1"/.test(align) ? 'W' : '';
  return { i, font: fontId, fill: fillId, border: borderId, numFmt: numFmtId, h, v, wrap };
});

console.log('=== FONTS ===');
fonts.forEach(f => console.log(`${f.i}: ${f.attr || '-'} sz=${f.sz} clr=${f.color || '-'} name=${f.name || '-'}`));
console.log('\n=== FILLS ===');
fills.forEach(f => console.log(`${f.i}: pf=${f.pf} fg=${f.fg || '-'} bg=${f.bg || '-'}`));
console.log('\n=== BORDERS ===');
borders.forEach(b => console.log(`${b.i}: L${b.l} R${b.r} T${b.t} B${b.b}`));
console.log('\n=== CELLXFS (style index → font/fill/border/numFmt/align) ===');
xfs.forEach(x => console.log(`${x.i}: f${x.font} fill${x.fill} bd${x.border} nf${x.numFmt} ${x.h}|${x.v}${x.wrap ? '|W' : ''}`));

