    const tre = /<t[^>]*>([^<]*)<\/t>/g;
    let txt = '';
    let tm;
    while ((tm = tre.exec(m[1]))) txt += tm[1];
    ss.push(txt);
  }
}

const sheet = fs.readFileSync(`${root}/xl/worksheets/sheet${sheetN}.xml`, 'utf8');

// Column widths
const colsBlock = /<cols>([\s\S]*?)<\/cols>/.exec(sheet)?.[1] || '';
const cols = [];
const colRe = /<col\s+([^/]+)\/>/g;
let cm;
while ((cm = colRe.exec(colsBlock))) {
  const a = cm[1];
  cols.push({
    min: /min="(\d+)"/.exec(a)?.[1],
    max: /max="(\d+)"/.exec(a)?.[1],
    width: /width="([^"]+)"/.exec(a)?.[1],
    hidden: /hidden="1"/.test(a) ? 'H' : '',
  });
}
console.log('COLS:', cols.map(c => `${c.min}-${c.max}=${c.width}${c.hidden}`).join(' | '));

// Merges
const merges = [];
const mergeRe = /<mergeCell ref="([^"]+)"\/>/g;
let mm;
while ((mm = mergeRe.exec(sheet))) merges.push(mm[1]);
console.log('MERGES:', merges.join(', '));

// Rows
const rowRe = /<row r="(\d+)"([^>]*)>([\s\S]*?)<\/row>/g;
let m;
while ((m = rowRe.exec(sheet))) {
  const r = m[1];
  const rowAttr = m[2];
  const ht = /ht="([^"]+)"/.exec(rowAttr)?.[1] || '';
  const inner = m[3];
  const cellRe = /<c r="([A-Z]+\d+)"(?: s="(\d+)")?(?: t="([^"]*)")?(?:\/>|>([\s\S]*?)<\/c>)/g;
  const cells = [];
  let cm2;
  while ((cm2 = cellRe.exec(inner))) {
    const ref = cm2[1];
    const st = cm2[2] || '';
    const type = cm2[3];
    const body = cm2[4] || '';
    let text = '';
    if (type === 's') {
      const idx = +(/<v>([^<]*)<\/v>/.exec(body)?.[1] ?? -1);
      text = ss[idx] ?? '';
    } else if (type === 'inlineStr') {
      text = (/<t[^>]*>([^<]*)<\/t>/.exec(body)?.[1] ?? '');
    } else {
      text = (/<v>([^<]*)<\/v>/.exec(body)?.[1] ?? '');
    }
    cells.push(`${ref}${st ? '/s' + st : ''}=${JSON.stringify(text)}`);
  }
  console.log(`r${r}${ht ? '[ht=' + ht + ']' : ''}: ${cells.join(' | ')}`);
}

