177	function stylesXml() {
178	  const fonts = `<fonts count="4">
179	<font><sz val="11"/><name val="Calibri"/></font>
180	<font><b/><sz val="11"/><name val="Calibri"/></font>
181	<font><b/><sz val="14"/><name val="Calibri"/></font>
182	<font><b/><sz val="12"/><name val="Calibri"/></font>
183	</fonts>`;
184	  const fills = `<fills count="6">
185	<fill><patternFill patternType="none"/></fill>
186	<fill><patternFill patternType="gray125"/></fill>
187	<fill><patternFill patternType="solid"><fgColor rgb="FFE7E6E6"/><bgColor rgb="FFE7E6E6"/></patternFill></fill>
188	<fill><patternFill patternType="solid"><fgColor rgb="FFFFF2CC"/><bgColor rgb="FFFFF2CC"/></patternFill></fill>
189	<fill><patternFill patternType="solid"><fgColor rgb="FFE2EFDA"/><bgColor rgb="FFE2EFDA"/></patternFill></fill>
190	<fill><patternFill patternType="solid"><fgColor rgb="FFDDEBF7"/><bgColor rgb="FFDDEBF7"/></patternFill></fill>
191	</fills>`;
192	  const borders = `<borders count="${BORDER_DEFS.length}">${BORDER_DEFS.join('')}</borders>`;
193	  const xfs = CELL_XFS.map(x => {
194	    const attrs = [
195	      'numFmtId="0"',
196	      `fontId="${x.font || 0}"`,
197	      `fillId="${x.fill || 0}"`,
198	      `borderId="${x.border || 0}"`,
199	      'xfId="0"',
200	    ];
201	    if (x.font) attrs.push('applyFont="1"');
202	    if (x.fill) attrs.push('applyFill="1"');
203	    if (x.border) attrs.push('applyBorder="1"');
204	    if (x.halign || x.valign || x.wrap) attrs.push('applyAlignment="1"');
205	    const align = (x.halign || x.valign || x.wrap)
206	      ? `<alignment${x.halign ? ` horizontal="${x.halign}"` : ''}${x.valign ? ` vertical="${x.valign}"` : ''}${x.wrap ? ' wrapText="1"' : ''}/>`
207	      : '';
208	    return `<xf ${attrs.join(' ')}>${align}</xf>`;
209	  }).join('');
210	  return `<?xml version="1.0" encoding="UTF-8" standalone="yes"?>
211	<styleSheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main">
212	${fonts}
213	${fills}
214	${borders}
215	<cellStyleXfs count="1"><xf numFmtId="0" fontId="0" fillId="0" borderId="0"/></cellStyleXfs>
216	<cellXfs count="${CELL_XFS.length}">${xfs}</cellXfs>
217	<cellStyles count="1"><cellStyle name="Normal" xfId="0" builtinId="0"/></cellStyles>
218	</styleSheet>`;
219	}
220	
221	// =============================================================
222	// Sheet rendering:
223	//   Input shape:  { cells: {A1:{v,s}, ...}, merges:["A1:C1",...], cols:[{min,max,width}], rowHeights:{1:24} }
224	// =============================================================
225	function sheetXml({ cells, merges = [], cols = [], rowHeights = {} }) {
226	  const grouped = new Map();
227	  for (const [ref, c] of Object.entries(cells)) {
228	    const m = ref.match(/^([A-Z]+)(\d+)$/);
229	    const rowIdx = +m[2];
230	    if (!grouped.has(rowIdx)) grouped.set(rowIdx, []);
231	    grouped.get(rowIdx).push({ ref, ...c });
232	  }
233	  const rowXmls = [];
234	  for (const rowIdx of [...grouped.keys()].sort((a, b) => a - b)) {
235	    const cs = grouped.get(rowIdx).sort((a, b) => a.ref.localeCompare(b.ref, undefined, { numeric: true }));
236	    const ht = rowHeights[rowIdx] ? ` ht="${rowHeights[rowIdx]}" customHeight="1"` : '';
237	    const cellXmls = cs.map(c => {
238	      // Emit s="0" explicitly — style 0 (default) must not be dropped, else
239	      // a cell with style 0 and no value becomes a naked <c r="X"/> which
240	      // Excel flags as recoverable corruption.
241	      const hasStyle = (c.s !== undefined && c.s !== null);
242	      const styleAttr = hasStyle ? ` s="${c.s}"` : '';
243	      const isEmpty = (c.v === undefined || c.v === null || c.v === '');
244	      if (isEmpty) {
245	        // Skip entirely when neither style nor value — avoids <c r="X"/>.
246	        if (!hasStyle) return '';
247	        return `<c r="${c.ref}"${styleAttr}/>`;
248	      }
249	      if (typeof c.v === 'number') {
250	        return `<c r="${c.ref}"${styleAttr}><v>${c.v}</v></c>`;
251	      }
