function textSheet(rows, opts = {}) {
  const cells = {};
  const rowHeights = {};
  const maxCols = Math.max(...rows.map(r => r.length));
  const explicitWidths = Array.isArray(opts.colWidths) ? opts.colWidths : null;

  // Pass 1 — column widths.
  const cols = [];
  if (explicitWidths) {
    // Group consecutive same widths into one <col> entry (matches Google Sheets output).
    let i = 0;
    while (i < explicitWidths.length) {
      const w = explicitWidths[i];
      let j = i;
      while (j + 1 < explicitWidths.length && explicitWidths[j + 1] === w) j++;
      cols.push({ min: i + 1, max: j + 1, width: w });
      i = j + 1;
    }
    // Trailing cols beyond explicit array fall back to WIDTH_MIN.
    if (explicitWidths.length < maxCols) {
      cols.push({ min: explicitWidths.length + 1, max: maxCols, width: WIDTH_MIN });
    }
  } else {
    // Auto-fit (CJK-aware). Cap per-cell contribution at WRAP_THRESHOLD so a single
    // giant description doesn't blow up the column — it wraps instead.
    for (let c = 0; c < maxCols; c++) {
      let maxVw = 0;
      for (const row of rows) {
        const vw = visualWidth(row[c] ?? '');
        maxVw = Math.max(maxVw, Math.min(vw, WRAP_THRESHOLD));
      }
      const width = Math.min(Math.max(maxVw + WIDTH_PADDING, WIDTH_MIN), WIDTH_MAX);
      cols.push({ min: c + 1, max: c + 1, width });
    }
  }

  // Header row gets explicit breathing room (REF baseline). 1-line cells in data rows
  // stay at the workbook default (~15) — only multi-line / long cells get bumped below.
  if (rows.length > 0) rowHeights[1] = HEADER_ROW_HEIGHT;

  function colWidthFor(cIdx) {
    for (const cg of cols) {
      if (cg.min <= cIdx + 1 && cIdx + 1 <= cg.max) return cg.width;
    }
    return WIDTH_MIN;
  }

  // Pass 2 — emit cells, apply wrap style for long values, compute row heights.
  rows.forEach((row, rIdx) => {
    let maxLines = 1;
    let anyLong = false;
    row.forEach((val, cIdx) => {
      const ref = R(rIdx, cIdx);
      const vw = visualWidth(val);
      const colW = colWidthFor(cIdx);
      const usable = Math.max(1, colW - WIDTH_PADDING);
      const isLong = vw > WRAP_THRESHOLD;
      // Header row 0 → style 4 (bold grey border, non-wrap) for short headers,
      //                style 24 (wrap header) when long.
      // Data rows    → style 23 (wrap + border) when long, else style 18
      //                (all-border + left align). Every data cell gets a
      //                border so the spec reads as a uniform grid.
      const style = rIdx === 0
        ? (isLong ? 24 : 4)
        : (isLong ? 23 : 18);
      cells[ref] = { v: val, s: style };
      if (isLong) {
        anyLong = true;
        const lines = Math.ceil(vw / usable);
        if (lines > maxLines) maxLines = lines;
      }
    });
    // Long-cell rows get a 2-line minimum (matches REF's pattern of 33.75-min on any
    // wrapped row, even when the wide column ends up rendering on 1 line). Header row
    // already has its explicit HEADER_ROW_HEIGHT — don't override.
    if (rIdx > 0 && anyLong) {
      const lines = Math.max(2, maxLines);
      rowHeights[rIdx + 1] = Math.min(lines * LINE_HEIGHT_PT, MAX_ROW_HEIGHT);
    }
  });

  return { cells, merges: [], cols, rowHeights };
}

