import fs from 'node:fs';

const path = process.argv[2];
let s = fs.readFileSync(path, 'utf8');
const hadCRLF = s.includes('\r\n');
if (hadCRLF) s = s.replace(/\r\n/g, '\n');

const subs = [
  [
    `const SHEETS_DATA = [\n  // Example — REPLACE:\n  // {\n  //   name: 'Overview',\n  //   rows: [\n  //     ['Field', 'Value'],\n  //     ['Object Name', '{OBJECT}'],\n  //     ['Object Type', '{TYPE}'],\n  //     // ...\n  //   ],\n  // },\n];`,
    `const SHEETS_DATA = [
  {
    name: "개요",
    colWidths: [26, 145.71],
    rows: [
      ["항목", "값"],
      ["오브젝트 이름", "ZMMR1001"],
      ["오브젝트 타입", "PROG/P (ABAP Report)"],
      ["짧은 설명", "ZMMR1001"],
      ["프로그램 제목", "MARA Semi-Finished Product (HALB) — Split ALV Viewer (OOP)"],
      ["패키지", "ZMM_PAEK"],
      ["아키타입", "Split ALV (Top/Bottom) — cl_gui_alv_grid + Docking + Splitter"],
      ["용도", "특정 plant의 반제품(MTART='HALB') 자재(MARA) 목록을 상단 그리드에 표시하고, 더블클릭 시 하단 그리드에서 자재별 상세(MAKT 설명, MARC plant, UoM, 자재 타입)를 동적으로 갱신. Docking + Splitter 컨테이너로 화면을 두 영역으로 분할한 OOP ALV 패턴."],
      ["청중", "Both (기능 + 기술)"],
      ["디테일 수준", "L2 Standard"],
      ["언어", "Korean"],
      ["SAP 버전", "S/4HANA (ABAP release 758)"],
      ["산업", "other"],
      ["인클루드", "없음 (단일 소스)"],
      ["로컬 클래스", "lcl_data (권한+조회) · lcl_alv (Docking/Splitter/2 grid) · lcl_event (top grid 더블클릭 핸들러)"],
      ["다이나로/GUI 상태", "Screen 1000 (선택 화면) + Screen 0100 (Docking 컨테이너 호스트, custom dynpro). GUI Status 0건 (CALL SCREEN 100, 표준 ALV 자체 toolbar 사용)"],
      ["호출 TCode", "없음 (외부 트랜잭션 호출 안 함)"],
      ["생성 일시", "2026-04-27 (SC4SAP /sc4sap:program-to-spec, L2 Korean)"],
      ["주의", "패키지 ZMM_PAEK는 표준 prefix 미준수 (개인 dev 패키지로 추정). UP TO 50 ROWS 제한이 있어 운영용 보고서로는 부적합 — 데모/테스트 한정. TEXT 심볼 (TEXT-b01/s01/t01/t02/f01..f05) 실제 값은 SE38에서 확인 필요 (텍스트 풀 fetch 실패)."],
    ],
  },
  {
    name: "데이터 모델",
    colWidths: [26, 12, 18, 16, 97.86],
    rows: [
      ["테이블", "접근", "키 필드", "조인 타입", "비고"],
      ["MARA", "R", "MATNR", "driver", "자재 마스터 (헤더). WHERE MTART='HALB' (반제품)"],
      ["MARC", "R", "MATNR, WERKS", "INNER JOIN", "Plant별 자재 (MARC~MATNR = MARA~MATNR), WHERE WERKS=P_WERKS"],
      ["MAKT", "R", "MATNR, SPRAS", "LEFT OUTER", "자재 텍스트. SPRAS=@SY-LANGU 조건으로 사용자 로그온 언어 텍스트만"],
      ["", "", "", "", ""],
      ["CDS Views", "—", "—", "—", "사용 안 함"],
      ["BAPI / RFC", "—", "—", "—", "사용 안 함"],
      ["BAdI / Enhancement", "—", "—", "—", "없음"],
    ],
  },
  {
    name: "처리 로직",
    colWidths: [12, 37, 141.29],
    rows: [
      ["#", "이벤트 / FORM / 메서드", "단계"],
      ["1",  "INITIALIZATION",                        "선택 화면 텍스트 세팅: %_p_werks_%_app_%-text = TEXT-s01 (P_WERKS 라벨)."],
      ["2",  "AT SELECTION-SCREEN OUTPUT",           "IF sy-dynnr = '0100' AND go_alv IS NOT BOUND → go_alv = NEW lcl_alv( ) + go_alv->display_initial( ). (lazy 인스턴스화)"],
      ["3",  "AT SELECTION-SCREEN",                  "IF sy-dynnr = '0100' AND sscrfields-ucomm = 'CRET' (F8 Execute) → CLEAR sscrfields-ucomm (보조 화면에서 stay)."],
      ["4",  "START-OF-SELECTION",                   "go_data = NEW lcl_data( ). 권한 체크 호출."],
      ["5",  "lcl_data->authorize",                  "AUTHORITY-CHECK OBJECT 'M_MATE_WRK' ID 'WERKS' FIELD iv_werks ID 'ACTVT' FIELD '03'. rv_ok = xsdbool( sy-subrc = 0 )."],
      ["6",  "START-OF-SELECTION (auth FAIL 분기)",  "IF authorize = abap_false → MESSAGE 'Not authorized for this plant' TYPE 'S' DISPLAY LIKE 'E' + RETURN."],
      ["7",  "lcl_data->fetch",                      "단일 SELECT 3-way JOIN: MARA AS a INNER JOIN MARC AS b ON b~matnr=a~matnr LEFT OUTER JOIN MAKT AS t ON t~matnr=a~matnr AND t~spras=@sy-langu. WHERE a~mtart=@gc_mtart_halb AND b~werks=@iv_werks. ORDER BY a~matnr. UP TO 50 ROWS INTO TABLE @et_data."],
      ["8",  "lcl_data->fetch (et_list 빌드)",       "et_list = VALUE #( FOR <ls> IN et_data ( matnr = <ls>-matnr ) ). SORT + DELETE ADJACENT DUPLICATES → 상단 그리드용 unique MATNR 리스트."],
      ["9",  "START-OF-SELECTION (empty 가드)",      "IF gt_data IS INITIAL → MESSAGE s013(s_unified_con) DISPLAY LIKE 'E' + RETURN."],
      ["10", "END-OF-SELECTION",                     "CHECK gt_data IS NOT INITIAL. DO ... CALL SCREEN 100 ... ENDDO. (사용자 escape로 sy-subrc<>0이면 lcl_alv->free + EXIT)"],
      ["11", "Screen 100 PBO (lcl_alv->constructor + display_initial)", "Docking 컨테이너 (DOCK_AT_TOP, extension=4000) → Splitter (rows=2, cols=1, top_height=40) → mo_grid_top + mo_grid_bot 생성 + lcl_event 핸들러 등록 (on_double_click FOR mo_grid_top)."],
      ["12", "lcl_alv->build_fcat_top",              "cl_salv_table=>factory + cl_salv_controller_metadata=>get_lvc_fieldcatalog로 동적 fcat 생성. MATNR 컬럼: coltext=TEXT-f01, outputlen=20, ref=MARA-MATNR."],
      ["13", "lcl_alv->build_fcat_bot",              "동일 패턴. MAKTX(TEXT-f02/40), WERKS(TEXT-f03/6), MEINS(TEXT-f04/5), MTART(TEXT-f05/6) 컬럼 텍스트/길이/ref 세팅."],
      ["14", "set_table_for_first_display (top)",    "is_layout: zebra=X, sel_mode='B', grid_title=TEXT-t01. it_outtab=gt_list (unique MATNR)."],
      ["15", "set_table_for_first_display (bot)",    "is_layout: zebra=X, grid_title=TEXT-t02. it_outtab=gt_detail (초기 비어있음)."],
      ["16", "lcl_event->on_double_click",           "READ TABLE gt_list INDEX e_row-index. CHECK sy-subrc=0. gt_detail = VALUE #( FOR <ls> IN gt_data WHERE ( matnr = ls_list-matnr ) ( maktx/werks/meins/mtart ) ) — 선택된 MATNR 기준 detail 행 추출."],
      ["17", "lcl_alv->refresh_bottom",              "mo_grid_bot->refresh_table_display( ) — 하단 그리드만 갱신 (상단은 그대로)."],
      ["18", "lcl_alv->free (loop 종료)",            "IF mo_dock IS BOUND → mo_dock->free + FREE: mo_grid_top, mo_grid_bot, mo_split, mo_dock. (메모리 누수 방지)"],
    ],
  },
  {
    name: "출력",
    colWidths: [12, 13, 26, 12, 12, 12, 55],
    rows: [
      ["순서", "필드", "필드 설명", "길이", "편집", "숨김", "비고"],
      ["1", "MATNR (top grid)", "자재 (Material)", "20", "N", "N", "TEXT-f01. 더블클릭 시 lcl_event=>on_double_click 호출 → 하단 detail 그리드 갱신. ref=MARA-MATNR."],
      ["", "", "── 하단 detail grid (top 더블클릭 시 갱신) ──", "", "", "", ""],
      ["2", "MAKTX", "자재 설명 (Description)", "40", "N", "N", "TEXT-f02. ref=MAKT-MAKTX. SPRAS=SY-LANGU 언어 텍스트."],
      ["3", "WERKS", "Plant", "6", "N", "N", "TEXT-f03. ref=MARC-WERKS. 입력값 P_WERKS 그대로."],
      ["4", "MEINS", "기본 단위 (UoM)", "5", "N", "N", "TEXT-f04. ref=MARA-MEINS."],
      ["5", "MTART", "자재 타입 (Type)", "6", "N", "N", "TEXT-f05. ref=MARA-MTART. 항상 'HALB' (필터링됨)."],
    ],
  },
  {
    name: "권한",
    colWidths: [35, 40, 29, 18, 61],
    rows: [
      ["체크", "권한 객체", "수준", "구현 여부", "비고"],
      ["Plant 단위 read 권한", "M_MATE_WRK", "프로그램 진입", "Yes (lcl_data~authorize)", "AUTHORITY-CHECK OBJECT 'M_MATE_WRK' ID 'WERKS' FIELD iv_werks ID 'ACTVT' FIELD '03'. ACTVT='03' (Display) 고정. 미통과 시 'Not authorized for this plant' 메시지 + RETURN."],
      ["S_TCODE", "—", "—", "Implicit", "트랜잭션 코드 자체는 별도 정의되지 않음 (REPORT 직접 실행 또는 ZMMR1001 TCode 정의 필요)."],
      ["S_PROGRAM (programexec)", "S_PROGRAM", "표준 SAP", "Implicit", "REPORT 실행 시 표준 SAP 권한 체크."],
      ["다른 ACTVT (Update/Delete 등) 차단", "M_MATE_WRK ACTVT=01/02/06", "—", "N/A", "본 프로그램은 read-only이므로 02 등 변경 권한은 무관. 다만 코드에서 ACTVT='03' 하드코딩이라 향후 update 기능 추가 시 별도 추가 필요."],
    ],
  },
  {
    name: "예외",
